eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\n/* harmony import */ var _features_EuropeanGallery_model_photos__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! @/features/EuropeanGallery/model/photos */ \"(rsc)/./src/features/EuropeanGallery/model/photos.ts\");\n\nconst el = {\n    nav: {\n        logoTitle: \"Μ.Δ. ΑΝΑΣΤΑΣΟΠΟΥΛΟΣ\",\n        logoSub: \"ΔΙΚΗΓΟΡΟΣ \\xb7 LL.M.\",\n        profile: \"ΠΡΟΦΙΛ\",\n        contact: \"ΕΠΙΚΟΙΝΩΝΙΑ\",\n        cta: \"ΕΠΙΚΟΙΝΩΝΗΣΤΕ\",\n        primaryNavigationLabel: \"Κύρια πλοήγηση\",\n        mobileNavigationLabel: \"Πλοήγηση κινητού\",\n        openMenuLabel: \"Άνοιγμα μενού\",\n        closeMenuLabel: \"Κλείσιμο μενού\"\n    },\n    hero: {\n        portraitsLabel: \"Φωτογραφίες πορτρέτου\",\n        selectPortrait: \"Προβολή πορτρέτου\",\n        chips: [\n            \"ΠΟΙΝΙΚΟ ΔΙΚΑΙΟ\",\n            \"ΑΘΗΝΑ \\xb7 ΚΟΛΩΝΑΚΙ\",\n            \"LL.M. IN INTERNATIONAL AND EUROPEAN LEGAL STUDIES\"\n        ],\n        label: \"ΔΙΚΗΓΟΡΟΣ \\xb7 ΑΘΗΝΑ\",\n        name1: \"Μιχαήλ Δ.\",\n        name2: \"Αναστασόπουλος\",\n        description: \"Μάχιμη δικηγορία με εξειδίκευση στο Ποινικό Δίκαιο, στρατηγική προσέγγιση, νομική ακρίβεια και προσήλωση στην υπεράσπιση.\"\n    },\n    about: {\n        label: \"ΠΡΟΦΙΛ\",\n        quote: \"\\xabΥπεράσπιση με στρατηγική, τεκμηρίωση και ακεραιότητα.\\xbb\",\n        bio: \"Ο Μιχάλης Αναστασόπουλος ασκεί μάχιμη δικηγορία στην Αθήνα, με κύρια και σταθερή ειδίκευση στο ποινικό δίκαιο και την υπεράσπιση σε σύνθετες και απαιτητικές υποθέσεις. Στο Δικηγορικό Γραφείο του Σάκη Κεχαγιόγλου συμμετέχει στην προετοιμασία και τεκμηρίωση σοβαρών ποινικών υποθέσεων, στη χάραξη στρατηγικής υπεράσπισης και στη διαχείριση υποθέσεων αυξημένης ευθύνης και πολυπλοκότητας.\",\n        affiliation: {\n            label: \"ΕΠΑΓΓΕΛΜΑΤΙΚΑ\",\n            name: \"Δικηγόρος Αθηνών\",\n            sub: \"Δικηγορικό Γραφείο Σ. Κεχαγιόγλου\"\n        },\n        academic: {\n            label: \"ΑΚΑΔΗΜΑΪΚΑ\",\n            degrees: [\n                \"LL.B. Νομικής, Δημοκρίτειο Πανεπιστήμιο Θράκης\",\n                \"LL.M. Διεθνείς & Ευρωπαϊκές Νομικές Σπουδές, Εθνικό & Καποδιστριακό Πανεπιστήμιο Αθηνών\"\n            ]\n        },\n        languagesLabel: \"ΓΛΩΣΣΕΣ\",\n        languagesValue: \"Ελληνικά \\xb7 Αγγλικά \\xb7 Γαλλικά \\xb7 Ρωσικά\"\n    },\n    practice: {\n        label: \"ΤΟΜΕΙΣ ΔΡΑΣΤΗΡΙΟΤΗΤΑΣ\",\n        items: [\n            {\n                number: \"01\",\n                title: \"Εγκλήματα κατά της ζωής\",\n                text: \"Υποθέσεις ανθρωποκτονίας, απόπειρας ανθρωποκτονίας, ανθρωποκτονίας από αμέλεια και σωματικών βλαβών.\"\n            },\n            {\n                number: \"02\",\n                title: \"Εγκλήματα κατά της ιδιοκτησίας & της περιουσίας\",\n                text: \"Υποθέσεις κλοπής, υπεξαίρεσης, ληστείας, φθοράς ξένης ιδιοκτησίας, εκβίασης, απάτης και απιστίας.\"\n            },\n            {\n                number: \"03\",\n                title: \"Ναρκωτικά\",\n                text: \"Υποθέσεις εισαγωγής, εξαγωγής, μεταφοράς, κατοχής και διακίνησης ναρκωτικών ουσιών.\"\n            },\n            {\n                number: \"04\",\n                title: \"Οικονομικό Ποινικό Δίκαιο\",\n                text: \"Υποθέσεις απάτης, υπεξαίρεσης, απιστίας, νομιμοποίησης εσόδων από εγκληματικές δραστηριότητες.\"\n            }\n        ]\n    },\n    academic: {\n        label: \"ΑΚΑΔΗΜΑΪΚΗ & ΕΠΑΓΓΕΛΜΑΤΙΚΗ ΠΟΡΕΙΑ\",\n        chaptersLabel: \"Μέρη\",\n        chapterLabel: \"ΜΕΡΟΣ\",\n        previousChapterLabel: \"Προηγούμενο μέρος\",\n        nextChapterLabel: \"Επόμενο μέρος\",\n        chapters: [\n            {\n                number: \"01\",\n                title: \"Επαγγελματική Πορεία\",\n                paragraphs: [\n                    \"Ο **Μιχάλης Αναστασόπουλος** είναι δικηγόρος Αθηνών και ασκεί μάχιμη δικηγορία με κύρια ενασχόληση το **ποινικό δίκαιο**. Από τα τέλη του **2023 έως σήμερα** συνεργάζεται με το **Δικηγορικό Γραφείο Σάκη Κεχαγιόγλου**, αποκτώντας καθημερινή και ουσιαστική εμπειρία στη διαχείριση σύνθετων και απαιτητικών ποινικών υποθέσεων.\",\n                    \"Η συνεργασία του με τον **Σάκη Κεχαγιόγλου**, μία από τις πλέον αναγνωρισμένες και εμβληματικές φυσιογνωμίες της ελληνικής ποινικής δικηγορίας, έχει αποτελέσει καθοριστικό σταθμό στην επαγγελματική του διαδρομή. Στο περιβάλλον αυτό, ο Μιχάλης Αναστασόπουλος συμμετέχει στην προετοιμασία και υποστήριξη ποινικών υποθέσεων, στη μελέτη σύνθετων δικογραφιών και στη διαμόρφωση της υπερασπιστικής γραμμής σε όλα τα κρίσιμα στάδια της ποινικής διαδικασίας.\"\n                ]\n            },\n            {\n                number: \"02\",\n                title: \"Σπουδές\",\n                paragraphs: [\n                    \"Είναι απόφοιτος της **Νομικής Σχολής του Δημοκριτείου Πανεπιστημίου Θράκης**, όπου ολοκλήρωσε τις προπτυχιακές του σπουδές στη Νομική. Στη συνέχεια ολοκλήρωσε μεταπτυχιακές σπουδές στο **Εθνικό και Καποδιστριακό Πανεπιστήμιο Αθηνών**, στο πρόγραμμα **LL.M. International & European Legal Studies**.\",\n                    \"Κατά τη διάρκεια των μεταπτυχιακών του σπουδών εστίασε στο **δίκαιο της Ευρωπαϊκής Ένωσης**, στη νομολογία του **Δικαστηρίου της Ευρωπαϊκής Ένωσης** και του **Ευρωπαϊκού Δικαστηρίου Δικαιωμάτων του Ανθρώπου**, στην προστασία των θεμελιωδών δικαιωμάτων, στο δίκαιο προστασίας προσωπικών δεδομένων και στον **GDPR**, καθώς και στο σύγχρονο ευρωπαϊκό κανονιστικό πλαίσιο για την ψηφιακή οικονομία.\"\n                ]\n            },\n            {\n                number: \"03\",\n                title: \"Έρευνα & Ενδιαφέροντα\",\n                paragraphs: [\n                    \"Ιδιαίτερο πεδίο του ακαδημαϊκού του ενδιαφέροντος αποτέλεσε η **ρύθμιση των ψηφιακών πλατφορμών στην Ευρωπαϊκή Ένωση**. Η μεταπτυχιακή του διπλωματική εργασία είχε ως αντικείμενο το ευρωπαϊκό κανονιστικό πλαίσιο των **Digital Services Act (DSA)** και **Digital Markets Act (DMA)** και τη θέση τους στο ευρύτερο σύστημα ρύθμισης των ψηφιακών αγορών και υπηρεσιών.\",\n                    \"Η ακαδημαϊκή του έρευνα επεκτάθηκε επίσης σε ζητήματα **προστασίας προσωπικών δεδομένων**, όπως η έννοια και η ευθύνη των κοινών υπευθύνων επεξεργασίας κατά τον GDPR, καθώς και σε ζητήματα **τεχνητής νοημοσύνης και πνευματικής ιδιοκτησίας**, με έμφαση στα ζητήματα που ανακύπτουν από τη χρήση προστατευόμενων έργων και δεδομένων για την εκπαίδευση μοντέλων γενετικής τεχνητής νοημοσύνης.\",\n                    \"Έχει ακόμη ασχοληθεί ακαδημαϊκά με την **ευθύνη στο διαδικτυακό περιβάλλον και την ελευθερία της έκφρασης**, το **ενεργειακό δίκαιο και την ευρωπαϊκή ενεργειακή και κλιματική διακυβέρνηση**, το **ευρωπαϊκό οικογενειακό δίκαιο**, την **προστασία του καταναλωτή**, καθώς και με ζητήματα που αφορούν τις **επιχειρήσεις και τα ανθρώπινα δικαιώματα**.\"\n                ]\n            },\n            {\n                number: \"04\",\n                title: \"Δράση & Γλώσσες\",\n                paragraphs: [\n                    \"Παράλληλα, δραστηριοποιείται ενεργά στον χώρο της ευρωπαϊκής πολιτικής νεολαίας, εκπροσωπώντας την **ΟΝΝΕΔ** σε συνέδρια, αποστολές και συναντήσεις της **Νεολαίας του Ευρωπαϊκού Λαϊκού Κόμματος (YEPP)**. Μέσα από τη συμμετοχή του αυτή, βρίσκεται σε διαρκή επαφή με τον ευρωπαϊκό πολιτικό και θεσμικό διάλογο, ιδίως σε ζητήματα δημοκρατίας, κράτους δικαίου, ευρωπαϊκής συνεργασίας και ενεργού συμμετοχής της νέας γενιάς στα κοινά.\",\n                    \"Γνωρίζει άριστα **αγγλικά**, ενώ μιλά επίσης **γαλλικά και ρωσικά**.\"\n                ]\n            }\n        ]\n    },\n    european: {\n        label: \"ΠΟΛΙΤΙΚΗ ΔΡΑΣΗ & ΕΥΡΩΠΑΪΚΗ ΠΑΡΟΥΣΙΑ\",\n        titleL1: \"Πολιτική Δράση &\",\n        titleL2: \"Ευρωπαϊκή Παρουσία\",\n        text: \"Ο Μιχάλης Αναστασόπουλος συμμετέχει ενεργά στον ευρωπαϊκό πολιτικό και θεσμικό διάλογο με σταθερή παρουσία στις δράσεις και τις διοργανώσεις της Νεολαίας του Ευρωπαϊκού Λαϊκού Κόμματος (YEPP), ως εκπρόσωπος της ΟΝΝΕΔ. Στο πλαίσιο αυτό, έχει εκπροσωπήσει την ΟΝΝΕΔ σε διεθνείς αποστολές, συνέδρια και πολιτικές συναντήσεις σε ευρωπαϊκό επίπεδο, με θεματικές που αφορούν τη δημοκρατία, το κράτος δικαίου, την ευρωπαϊκή συνεργασία, την ψηφιακή διακυβέρνηση και τη συμμετοχή της νέας γενιάς στη δημόσια και πολιτική ζωή.\",\n        affiliationLabel: \"YEPP \\xb7 ΟΝΝΕΔ\",\n        galleryLabel: \"ΕΥΡΩΠΑΪΚΕΣ ΣΥΝΑΝΤΗΣΕΙΣ\",\n        previousPhoto: \"Προηγούμενη φωτογραφία\",\n        nextPhoto: \"Επόμενη φωτογραφία\",\n        enlargePhoto: \"Προβολή σε πλήρες μέγεθος\",\n        closeGallery: \"Κλείσιμο προβολής\",\n        photos: (0,_features_EuropeanGallery_model_photos__WEBPACK_IMPORTED_MODULE_0__.getEuropeanPhotos)([\n            {\n                caption: \"Συνέδριο YEPP\",\n                alt: \"Συμμετοχή σε συνέδριο με την ελληνική αντιπροσωπεία\"\n            },\n            {\n                caption: \"Εκπροσώπηση της ΟΝΝΕΔ\",\n                alt: \"Συμμετοχή στις εργασίες συνεδρίου της YEPP\"\n            },\n            {\n                caption: \"Διάλογος & συνεργασία\",\n                alt: \"Συζήτηση με μέλη ευρωπαϊκών αντιπροσωπειών\"\n            },\n            {\n                caption: \"Θεσμικός διάλογος\",\n                alt: \"Τοποθέτηση σε μικρόφωνο κατά τη διάρκεια θεσμικής συνάντησης\"\n            },\n            {\n                caption: \"Παρέμβαση σε συνέδριο\",\n                alt: \"Παρέμβαση με μικρόφωνο σε συνέδριο\"\n            },\n            {\n                caption: \"Ευρωπαϊκές συναντήσεις\",\n                alt: \"Συζήτηση σε ευρωπαϊκή συνάντηση εργασίας\"\n            }\n        ])\n    },\n    contact: {\n        form: {\n            \"label\": \"Φόρμα επικοινωνίας\",\n            \"required\": \"Όλα τα πεδία είναι υποχρεωτικά.\",\n            \"firstName\": \"Όνομα\",\n            \"lastName\": \"Επώνυμο\",\n            \"phone\": \"Τηλέφωνο\",\n            \"email\": \"Email\",\n            \"message\": \"Το μήνυμά σας\",\n            \"submit\": \"Αποστολή μηνύματος\",\n            \"sending\": \"Αποστολή…\",\n            \"success\": \"Το μήνυμά σας εστάλη. Σας ευχαριστούμε για την επικοινωνία.\",\n            \"error\": \"Το μήνυμα δεν εστάλη. Δοκιμάστε ξανά ή επικοινωνήστε μέσω email ή τηλεφώνου.\"\n        },\n        label: \"ΕΠΙΚΟΙΝΩΝΙΑ\",\n        title: \"Κάθε υπόθεση είναι διαφορετική.\",\n        text: \"Η προσεκτική αξιολόγηση των δεδομένων και η έγκαιρη νομική καθοδήγηση μπορούν να αποδειχθούν καθοριστικές.\",\n        invitation: \"Για την αξιολόγηση της υπόθεσής σας, μπορείτε να επικοινωνήσετε άμεσα.\",\n        cta: \"ΑΠΟΣΤΟΛΗ ΜΗΝΥΜΑΤΟΣ\",\n        emailLabel: \"EMAIL\",\n        phoneLabel: \"ΤΗΛΕΦΩΝΟ\"\n    },\n    footer: {\n        copy: \"Μιχαήλ Δ. Αναστασόπουλος\",\n        developedBy: \"Ανάπτυξη από GroundWork Studio\"\n    }\n};\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (el);\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(rsc)/./src/i18n/dictionaries/el.ts\n");

